import { YtdlError } from "../errors.js";
import { LIVE_IDLE_MS, waitUntil } from "./session.js";
// YouTube live segments last about 5 s.
const DEFAULT_TARGET_DURATION = 5;
// YouTube's MPEG-TS live playlists carry no `#EXT-X-MAP`, `#EXT-X-KEY` or discontinuities.
function parsePlaylist(text, baseUrl) {
    const lines = text.split(/\r?\n/u).map((line) => line.trim());
    if (lines[0] !== "#EXTM3U")
        throw new YtdlError("REQUEST_FAILED", "The live playlist is not an HLS playlist");
    let sequence = 0;
    let targetDuration = DEFAULT_TARGET_DURATION;
    let duration = 0;
    let ended = false;
    const segments = [];
    for (const line of lines) {
        if (line.startsWith("#EXT-X-MEDIA-SEQUENCE:"))
            sequence = Number.parseInt(line.slice(22), 10);
        else if (line.startsWith("#EXT-X-TARGETDURATION:"))
            targetDuration = Number.parseFloat(line.slice(22));
        else if (line.startsWith("#EXTINF:"))
            duration = Number.parseFloat(line.slice(8));
        else if (line === "#EXT-X-ENDLIST")
            ended = true;
        else if (line !== "" && !line.startsWith("#")) {
            segments.push({ sequence: sequence++, duration, uri: new URL(line, baseUrl).href });
            duration = 0;
        }
    }
    return { targetDuration, segments, ended };
}
function startSequence(playlist, liveBuffer) {
    const { segments } = playlist;
    let start = (segments.at(-1)?.sequence ?? -1) + 1;
    if (playlist.ended)
        return segments[0]?.sequence ?? start;
    let buffered = 0;
    for (const segment of segments.toReversed()) {
        if (buffered >= liveBuffer / 1000)
            break;
        buffered += segment.duration;
        start = segment.sequence;
    }
    return start;
}
export async function* readLive(session, liveBuffer, signal) {
    let next;
    let freshAt = Date.now();
    let targetDuration = DEFAULT_TARGET_DURATION;
    poll: for (;;) {
        const polledAt = Date.now();
        const url = session.format.url ?? "";
        const response = await session.request(url, { retryLaterMs: targetDuration * 1000 });
        if (!response)
            continue;
        const text = await session.read(response, (body) => body.text());
        if (text === undefined)
            continue;
        const playlist = parsePlaylist(text, url);
        ({ targetDuration } = playlist);
        next ??= startSequence(playlist, liveBuffer);
        let fresh = false;
        for (const segment of playlist.segments) {
            if (segment.sequence < next)
                continue;
            const media = await session.request(segment.uri, { retryLaterMs: targetDuration * 1000 });
            // A resumed playlist's segment URLs replace the old, expired ones.
            if (!media)
                continue poll;
            const bytes = await session.read(media, (body) => body.bytes());
            if (!bytes)
                continue poll;
            if (bytes.length > 0) {
                session.progress(bytes.length, undefined);
                yield bytes;
            }
            next = segment.sequence + 1;
            fresh = true;
            freshAt = Date.now();
        }
        if (playlist.ended || Date.now() - freshAt >= LIVE_IDLE_MS)
            return;
        // RFC 8216 6.3.4: reload after a target duration, or half of one when nothing was new.
        await waitUntil(polledAt + (fresh ? 1000 : 500) * targetDuration, signal);
    }
}
